use std::{net::SocketAddr,sync::{Arc,atomic::{AtomicUsize,Ordering}}}; use tokio::{net::UdpSocket,sync::{mpsc,RwLock,watch}}; use crate::stats::Stats;
pub const returnChBuf:usize=512; pub const chunkSize:usize=12; pub fn getPktBuf(size:usize)->Vec<u8>{vec![0;size]} pub fn putPktBuf(_:Vec<u8>){}
pub struct WorkerSlot {pub ID:i32,pub SendCh:mpsc::Sender<Vec<u8>>}
pub struct Dispatcher { pub localConn:Arc<UdpSocket>, clientAddr:RwLock<Option<SocketAddr>>, workers:RwLock<Vec<Arc<WorkerSlot>>>, rrIndex:AtomicUsize, pub ReturnCh:mpsc::Sender<Vec<u8>>, returnRx:tokio::sync::Mutex<mpsc::Receiver<Vec<u8>>>, shutdown:watch::Sender<bool>, stats:Arc<Stats> }
pub async fn NewDispatcher(localConn:UdpSocket,stats:Arc<Stats>)->Arc<Dispatcher>{let (tx,rx)=mpsc::channel(returnChBuf);let (shutdown,_)=watch::channel(false);Arc::new(Dispatcher{localConn:Arc::new(localConn),clientAddr:RwLock::new(None),workers:RwLock::new(vec![]),rrIndex:AtomicUsize::new(0),ReturnCh:tx,returnRx:tokio::sync::Mutex::new(rx),shutdown,stats})}
impl Dispatcher { pub async fn Shutdown(&self){let _=self.shutdown.send(true);} pub async fn Register(&self,w:Arc<WorkerSlot>){self.workers.write().await.push(w)} pub async fn Unregister(&self,id:i32){self.workers.write().await.retain(|w|w.ID!=id)} pub async fn readLoop(self:Arc<Self>){let mut b=[0;2048];loop{let Ok((n,a))=self.localConn.recv_from(&mut b).await else{return};*self.clientAddr.write().await=Some(a);self.stats.TotalBytesUp.fetch_add(n as i64,Ordering::Relaxed);let w=self.workers.read().await;if !w.is_empty(){let i=self.rrIndex.fetch_add(1,Ordering::Relaxed)/chunkSize%w.len();let _=w[i].SendCh.try_send(b[..n].to_vec());}}} pub async fn writeLoop(self:Arc<Self>){loop{let p={self.returnRx.lock().await.recv().await};let Some(p)=p else{return};if let Some(a)=*self.clientAddr.read().await{let _=self.localConn.send_to(&p,a).await;self.stats.TotalBytesDown.fetch_add(p.len()as i64,Ordering::Relaxed);}}} }
